'use client';

import { useRef } from 'react';
import { usePlayback } from './use-playback';
import './indeterminate-loader.css';

export interface IndeterminateLoaderProps {
  /** Accessible name, for example "Loading charts". */
  label: string;
  /** False shows a full, finished bar. */
  active?: boolean;
  className?: string;
}

/**
 * A bar for work of unknown length: a segment runs across it while active.
 * Off screen or in a hidden tab the loop pauses; with reduced motion the
 * bar is still and a "Loading…" label carries the message.
 */
export function IndeterminateLoader({
  label,
  active = true,
  className = '',
}: IndeterminateLoaderProps) {
  const root = useRef<HTMLDivElement>(null);
  const playing = usePlayback(root, !active);
  return (
    <div
      ref={root}
      className={`mg-loader ${className}`}
      data-active={active}
      data-playing={playing}
    >
      <div
        className='mg-loader__track'
        role='progressbar'
        aria-label={label}
        aria-busy={active}
        aria-valuemin={active ? undefined : 0}
        aria-valuemax={active ? undefined : 100}
        aria-valuenow={active ? undefined : 100}
      >
        <span className='mg-loader__bar' />
      </div>
      <span className='mg-loader__text'>
        {active ? `${label}…` : `${label}: done`}
      </span>
    </div>
  );
}

.mg-loader {
  display: grid;
  gap: 8px;
  color: var(--mg-text, #ffffff);
}

.mg-loader__track {
  position: relative;
  height: 8px;
  overflow: hidden;
  border-radius: 4px;
  background: #262626;
}

.mg-loader__bar {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 40%;
  border-radius: 4px;
  background: var(--mg-accent, #eaf2fb);
  animation: mg-loader-run 1.3s cubic-bezier(0.45, 0, 0.55, 1) infinite;
  animation-play-state: paused;
}

.mg-loader[data-playing='true'] .mg-loader__bar {
  animation-play-state: running;
}

.mg-loader[data-active='false'] .mg-loader__bar {
  width: 100%;
  background: var(--mg-accent, #eaf2fb);
  animation: mg-loader-finish 300ms ease-out;
}

.mg-loader__text {
  color: #b8b8b8;
  font-size: 13px;
}

@keyframes mg-loader-run {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(250%);
  }
}

@keyframes mg-loader-finish {
  from {
    transform: scaleX(0.4);
    transform-origin: left;
  }
}

/* Still: a static, striped bar; the label says "Loading…". */
@media (prefers-reduced-motion: reduce) {
  .mg-loader__bar {
    width: 100%;
    animation: none;
    background: repeating-linear-gradient(
      135deg,
      var(--mg-accent, #eaf2fb) 0 8px,
      #dce9f7 8px 16px
    );
  }
  .mg-loader[data-active='false'] .mg-loader__bar {
    animation: none;
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}
